uniform shader image;
uniform float2 size;
uniform float phase;
uniform float amount;
uniform float scale;
layout(color) uniform half4 tint;
float hash(float2 p){return fract(sin(dot(p,float2(127.1,311.7)))*43758.5453);}half4 effectMain(float2 coord){half4 c=image.eval(coord);float2 p=coord/size-0.5;float a=atan(p.y,p.x);float r=length(p);float orbit=abs(fract(a*4.0/6.2831853+phase*0.1+hash(floor(a*10.0))*0.3)-0.5);float m=(1.0-smoothstep(0.02,0.08,orbit))*step(r,0.45)*amount;return half4(clamp(c.rgb+tint.rgb*half(m)*c.a,half3(0),half3(1)),c.a);}
uniform float effectOpacity;
half4 main(float2 coord) {
    half4 original = image.eval(coord);
    half4 processed = effectMain(coord);
    return mix(original, processed, half(clamp(effectOpacity, 0.0, 1.0)));
}
